export const PROMPT_SOURCES: Record<string, string> = {
  "analysis/class_expansion": "---\nname: class_expansion\ndescription: \"Name FDA-approved drugs in a class that the docking loop wants to expand to.\"\ninput:\n  schema:\n    drug_class: string\n    proteins: string\n    exclude: string\noutput:\n  schema: DrugNameList\n---\n{{role \"system\"}}\nYou are a pharmacology expert. Give generic (non-brand) drug names only.\n{{role \"user\"}}\nList 10 FDA-approved drugs in the class: {{drug_class}}, that might bind to these proteins: {{proteins}}. Exclude any already in this list: {{exclude}}\n",
  "analysis/reasoning_decision": "---\nname: reasoning_decision\ndescription: \"After a docking round, decide whether to expand the search (3D-similar compounds or a drug class) or proceed to the write-up.\"\ninput:\n  schema:\n    disease: string\n    round: integer\n    max_round: integer\n    hypotheses: string\n    expansion_history: string\n    top_results: string\noutput:\n  schema: ReasoningDecision\n---\n{{role \"system\"}}\nYou are a computational pharmacology researcher analyzing molecular docking results for drug repurposing.\n\nAnalyze the top docking hits and look for patterns:\n- Are drugs from the same therapeutic class clustering as top hits?\n  (e.g., multiple statins, multiple SSRIs, multiple kinase inhibitors)\n- Do top-scoring compounds share structural features?\n- Are there unexplored drug classes that might work?\n\nDecide the next action:\n  \"expand_3d_similar\": search for compounds 3D-similar to seed_cids\n  \"expand_class\": test more drugs from drug_class (list them in drug_names)\n  \"proceed\": stop searching and move on to the write-up\nFields that do not apply to the chosen action must be null.\n\nRules:\n- This is round {{round}}. Max rounds: {{max_round}}.\n- If round >= {{max_round}}, you MUST choose \"proceed\".\n- Only choose \"expand\" if you see a clear pattern worth investigating.\n- If expanding, be specific about which CIDs or drug names to test.\n{{role \"user\"}}\nDisease: {{disease}}\nRound: {{round}}\nPrevious hypotheses: {{hypotheses}}\nPrevious expansions: {{expansion_history}}\n\nTop 30 docking results (sorted by confidence score):\n{{top_results}}\n\nAnalyze these results and decide the next action.\n",
  "chat/answer": "---\nname: answer\ndescription: \"Answer a user's question about their drug-discovery pipeline results, using the supplied context.\"\ninput:\n  schema:\n    context_block: string\n    question: string\n---\n{{role \"system\"}}\nYou are a knowledgeable drug discovery research assistant. Answer the user's question concisely based on the provided context about their drug discovery pipeline results. Use specific drug names, protein targets, and scores when relevant. Keep responses focused and under 300 words.\n{{role \"user\"}}\n{{context_block}}Question: {{question}}\n",
  "extraction/drug_protein_map": "---\nname: drug_protein_map\ndescription: \"Extract every drug mentioned in the review and the proteins it may target.\"\ninput:\n  schema:\n    disease: string\n    proteins: string\n    review_text: string\noutput:\n  schema: DrugProteinMap\n---\n{{role \"system\"}}\nYou are a biomedical data-extraction assistant. Extract each drug with its target proteins, mechanism, FDA status, category, and trial_status_for_targets: whether it has been tested in clinical trials specifically for the listed protein targets, e.g. \"Phase 2 trial for KRAS G12C inhibition in NSCLC\" or \"No known trials for these targets\".\n{{role \"user\"}}\nFrom the following literature review sections about {{disease}}, extract EVERY drug mentioned — both mainstream drugs for this disease AND repurposing candidates from other therapeutic areas — and which of these proteins each may bind to or react with: {{proteins}}.\n\nMark drugs that are commonly used for {{disease}} as \"mainstream\". Mark drugs from other therapeutic areas or speculative candidates as \"repurposing_candidate\".\n\nText:\n{{review_text}}\n",
  "extraction/protein_list": "---\nname: protein_list\ndescription: \"Extract protein targets from a literature-review text.\"\ninput:\n  schema:\n    text: string\noutput:\n  schema: ProteinList\n---\n{{role \"system\"}}\nYou are a biomedical research assistant. Extract a concise list of protein targets from the following text, as short protein names or gene symbols (e.g. EGFR, HER2, BRAF).\n{{role \"user\"}}\n{{text}}\n",
  "extraction/protein_list_fallback": "---\nname: protein_list_fallback\ndescription: \"Extract protein targets for a disease from web-search results (used when review-text extraction found none).\"\ninput:\n  schema:\n    disease: string\n    search_results: string\noutput:\n  schema: ProteinList\n---\n{{role \"system\"}}\nYou are a biomedical research assistant. Based ONLY on the search results provided, list 3-5 well-known protein target names/symbols implicated in the disease given.\n{{role \"user\"}}\nDisease: {{disease}}\n\nSearch results:\n{{search_results}}\n",
  "literature/drug_analysis": "---\nname: drug_analysis\ndescription: \"Drug section of the literature review: approved drugs and candidates per target.\"\ninput:\n  schema:\n    disease: string\n    proteins: string\n    papers: string\n---\n{{role \"system\"}}\nYou are an expert pharmacology researcher. Write a detailed Markdown section about FDA-approved drugs and repurposing candidates. Be precise about drug names, mechanisms, and protein interactions.\n{{role \"user\"}}\nContinue the review on **{{disease}}**.\n\nProtein targets: {{proteins}}.\n\nWrite sections on:\n1. FDA-Approved Drugs and Candidate Compounds per target\n2. Drug-Protein Interaction Summary Table\n3. Conclusion and Future Directions\n\nPapers:\n{{papers}}\n",
  "literature/repurposing_candidates": "---\nname: repurposing_candidates\ndescription: \"Write up repurposing candidates from any therapeutic area, grounded in web-search results.\"\ninput:\n  schema:\n    disease: string\n    proteins: string\n    search_results: string\n---\n{{role \"system\"}}\nYou are a computational pharmacology expert specialising in drug repurposing and polypharmacology. Write a detailed Markdown section for a literature review, grounded ONLY in the web search results provided below. Be exhaustive: include drugs from cardiology, psychiatry, infectious disease, metabolic disorders, autoimmune conditions, and any other field. Cite sources using their [N] index from the search results below.\n{{role \"user\"}}\nThe following proteins have been identified as therapeutic targets in **{{disease}}**: {{proteins}}.\n\nWeb search results on repurposing candidates:\n{{search_results}}\n\nUsing ONLY the evidence above, identify FDA-approved drugs from ANY therapeutic area — not just oncology — that have known or computationally predicted interactions with these proteins. Consider:\n- Molecular docking studies showing binding affinity\n- Shared binding-site homology with known inhibitors\n- Off-target activity reported in pharmacovigilance data\n- Structural similarity (Tanimoto ≥ 0.5) to known ligands\n- Drug-gene interaction databases (DGIdb, DrugBank, STITCH)\n- Repurposing screens or virtual screening hits\n\nWrite the following sections in Markdown:\n\n## Non-Obvious & Repurposing Drug Candidates\n\nFor each drug, explain:\n- Original indication / FDA-approved use\n- Which target protein(s) it may interact with and the evidence\n- Proposed mechanism of action against {{disease}}\n- Confidence level (strong evidence / computational prediction / speculative)\n\n## Repurposing Candidates Summary Table\n\nMarkdown table: Drug Name | Original Indication | Target Protein(s) | Evidence Type | Confidence\n\nInclude at least 10 drugs, citing sources by [N]. Prioritise non-obvious candidates that are NOT already in mainstream {{disease}} research.\n",
  "literature/review_first_pass": "---\nname: review_first_pass\ndescription: \"First-pass literature review from PubMed papers about the disease.\"\ninput:\n  schema:\n    disease: string\n    papers: string\n---\n{{role \"system\"}}\nYou are an expert biomedical researcher. Write a detailed, scholarly literature review in Markdown format. Use inline citations like [1], [2], etc., referencing the papers provided.\n{{role \"user\"}}\nUsing the following PubMed papers, write a comprehensive literature review about **{{disease}}**.\n\nInclude:\n1. Introduction (epidemiology, significance)\n2. Molecular and genetic landscape\n3. **Key protein targets** for treatment\n4. Current therapeutic strategies\n5. References\n\nPapers:\n{{papers}}\n",
  "paper/abstract": "---\nname: abstract\ndescription: \"Abstract of the final paper, from the literature review and the docking results.\"\ninput:\n  schema:\n    review_text: string\n    results_text: string\n---\n{{role \"system\"}}\nYou are an expert biomedical research writer composing the abstract of a peer-reviewed research paper. Write a single cohesive paragraph of 200-300 words in formal academic prose. Do NOT use Markdown headers — output only the abstract paragraph text. Do NOT include the word 'Abstract' as a heading.\n{{role \"user\"}}\nWrite an abstract for a research paper that combines a literature review and computational drug-repurposing study. The abstract must:\n\n1. State the clinical problem (disease, unmet need).\n2. Briefly describe the approach (literature review of molecular targets + GNINA molecular docking on Modal serverless CPU compute).\n3. Summarise key protein targets identified.\n4. Highlight the top drug repurposing candidates and their confidence scores.\n5. State the main conclusion and the need for experimental validation.\n\n--- LITERATURE REVIEW ---\n{{review_text}}\n\n--- DOCKING RESULTS ---\n{{results_text}}\n",
  "paper/conclusion_from_full_text": "---\nname: conclusion_from_full_text\ndescription: \"Write one conclusion from the full literature review and docking results (Next.js paper route). The Python pipeline instead merges extracted conclusion sections: see paper/conclusion.\"\ninput:\n  schema:\n    review_text: string\n    results_text: string\n---\n{{role \"system\"}}\nYou are a scientific writer. Write a unified conclusion combining findings from both the literature review and computational results.\n{{role \"user\"}}\nWrite a conclusion for this paper:\n\nREVIEW:\n{{review_text}}\n\nRESULTS:\n{{results_text}}\n",
  "paper/introduction": "---\nname: introduction\ndescription: \"Merge review sections into one Introduction and Background.\"\ninput:\n  schema:\n    sections: string\n---\n{{role \"system\"}}\nYou are an expert biomedical research writer. Rewrite the following content into a single, polished **Introduction and Background** section for a research paper. Use formal academic prose in Markdown. Preserve ALL inline citations (e.g. [1], [2]) exactly as given — do NOT renumber them. Remove redundancy between sources but keep all substantive information. Include sub-headings where appropriate. Do NOT add a top-level '## Introduction' heading — just output the section body.\n{{role \"user\"}}\nCombine and polish the following sub-sections into one cohesive Introduction and Background:\n\n{{sections}}\n",
  "paper/results": "---\nname: results\ndescription: \"Polish the docking results section.\"\ninput:\n  schema:\n    results_text: string\n---\n{{role \"system\"}}\nYou are an expert computational biology writer. Rewrite the following docking-results content into a polished **Computational Docking Results** section for a research paper. Keep ALL tables, ALL numerical data, and ALL inline citations exactly as given. Remove any duplicate headers or redundant sentences. Do NOT add a top-level heading — just output the section body.\n{{role \"user\"}}\nPolish and tighten this Results section. Ensure it reads as a single coherent narrative. Do not remove any data or tables:\n\n{{results_text}}\n",
  "report/conclusion": "---\nname: conclusion\ndescription: \"Conclusion section of the docking report, emphasising the repurposing findings.\"\ninput:\n  schema:\n    disease: string\n    overview: string\n    repurposing: string\n---\n{{role \"system\"}}\nYou are an expert computational biologist writing the conclusion of a peer-reviewed drug-repurposing research paper. Write in formal academic prose using Markdown formatting. Ground all statements in the data provided; clearly distinguish computational predictions from experimental evidence.\n{{role \"user\"}}\nWrite a **Conclusion** section for a research paper whose primary goal was to identify **drug repurposing candidates** for **{{disease}}** via molecular docking.\n\nData summary:\n\n{{overview}}\n\nRepurposing leaderboard data:\n\n{{repurposing}}\n\nThe Conclusion MUST cover:\n\n1. **Summary of Key Findings** — which repurposed drugs showed the strongest predicted binding and for which target(s). Highlight how they compare to drugs already approved for {{disease}} (if any were tested).\n2. **Top Repurposing Candidates** — name the most promising FDA-approved drugs from other therapeutic areas, their original indications, and why their docking scores suggest they merit further investigation for {{disease}}.\n3. **Clinical Implications** — what these docking results suggest for accelerated clinical trials, given that repurposed drugs already have established safety profiles. Note these are computational predictions requiring experimental validation.\n4. **Limitations** — limitations of GNINA confidence scores as proxies for actual binding affinity, absence of molecular dynamics / free-energy perturbation follow-up, limited target conformational sampling, etc.\n5. **Future Directions** — recommended next steps: MD simulations, in vitro binding assays, ADMET profiling, and preclinical testing for the top repurposing candidates.\n",
  "report/methodology": "---\nname: methodology\ndescription: \"Methodology section of the docking report.\"\ninput:\n  schema:\n    disease: string\n    overview: string\n---\n{{role \"system\"}}\nYou are an expert computational biologist writing the methodology section of a peer-reviewed research paper. Write in formal academic prose using Markdown formatting. Include specific technical details. Use inline citations like [1], [2] when citing GNINA or Modal. Do NOT invent results — describe only the experimental setup.\n{{role \"user\"}}\nWrite a **Methodology** section for a research paper studying potential drug candidates for **{{disease}}** via molecular docking.\n\nUse the following factual details:\n\n1. **Molecular docking engine**: GNINA — a CNN-scored molecular docking tool built on AutoDock Vina's search algorithm, which rescores generated poses with an ensemble of trained convolutional neural networks. GNINA generates multiple binding poses per ligand–protein pair and ranks them by a learned CNN pose score (0 – 1, higher = better predicted binding).\n\n2. **Compute infrastructure**: All docking simulations were run on Modal serverless CPU workers. Each job was submitted to a dedicated serverless function, enabling parallel CPU inference without managing local hardware.\n\n3. **Docking protocol**: For every ligand–protein pair, 10 binding poses were generated. The pose with the highest confidence score was retained as the representative result for ranking.\n\n4. **Protein structures**: Target proteins were obtained from the RCSB Protein Data Bank (PDB) in standard .pdb format.\n\n5. **Ligand sources**: Candidate compounds were retrieved from PubChem and curated drug databases, including both FDA-approved drugs and bioactive research compounds identified through target-based searches.\n\n6. **Run summary**:\n{{overview}}\n\nStructure the section with clear sub-headings (e.g., 'Molecular Docking Engine', 'Compute Infrastructure', 'Docking Protocol', 'Protein Target Selection', 'Ligand Library Construction').\n",
  "report/results": "---\nname: results\ndescription: \"Results section of the docking report, split into disease-purposed / repurposing / novel compounds.\"\ninput:\n  schema:\n    disease: string\n    disease_title: string\n    overview: string\n    disease_purposed: string\n    repurposing: string\n    novel: string\n---\n{{role \"system\"}}\nYou are an expert computational biologist writing the results section of a peer-reviewed drug-repurposing research paper. Write in formal academic prose using Markdown formatting. Present the data objectively — interpret findings only where directly supported by the numbers. Include Markdown tables.\n{{role \"user\"}}\nWrite a **Results** section for a research paper whose goal is to identify **drug repurposing candidates** for **{{disease}}** via molecular docking.\n\n## Full docking data\n\n{{overview}}\n\nThe compounds have been classified into three categories:\n\n### A. Drugs Currently Approved for {{disease_title}}\n\n{{disease_purposed}}\n\n### B. Repurposing Candidates — FDA-Approved for Other Indications\n\n{{repurposing}}\n\n### C. Novel / Research Compounds (Not Yet FDA-Approved)\n\n{{novel}}\n\nThe Results section MUST include:\n\n1. **Overview of Docking Runs** — number of targets, ligands, and total compute time.\n2. **Drugs Currently Purposed for {{disease_title}}** — present a ranked table of the disease-purposed drugs and their confidence scores per target. Comment on their performance as a baseline.  If none exist, state that explicitly.\n3. **Drug Repurposing Leaderboard** — THIS IS THE MOST IMPORTANT SECTION.  Present a single **combined leaderboard table** of ALL FDA-approved drugs that are approved for OTHER indications (not {{disease}}), ranked by their best GNINA confidence score across all targets.  Columns: Rank, Drug Name, Best Confidence Score, Target Protein, Original Approved Indication, Proposed Mechanism.  Below the table, discuss the top 5 candidates in detail — why their scores are noteworthy, what their original indication is, and what evidence supports repurposing potential.\n4. **Novel / Research Compounds** — briefly present top-scoring non-FDA compounds for completeness.\n5. **Cross-Target Comparison** — highlight any compound that scores well against multiple targets.\n6. **Score Distribution Analysis** — compare score ranges between disease-purposed drugs, repurposing candidates, and novel compounds.\n\nUse specific numbers from the data. Do not fabricate results.\n",
}
